const input = $input.first().json;
const hasPhoto = input.hasPhoto;
const photoId = input.photoId;
const content = input.content || '';

return {
  hasPhoto: hasPhoto,
  photoId: photoId,
  content: content,
  chatId: input.chatId,
  systemPrompt: `You are an expert visual content strategist for LinkedIn. Your role is to analyze images and suggest visual enhancements for posts.

Based on the content and any provided images, decide:
1. If images should be included in the final post
2. What type of image would best complement the content
3. Image placement and sizing recommendations
4. Alternative image suggestions if needed

Format your response as JSON with these fields:
{
  "includeInPost": "boolean",
  "imageUrl": "string (if existing image)",
  "imageAnalysis": "string",
  "recommendations": ["array"],
  "generateNew": "boolean",
  "imageDescription": "string (for generation)"
}`
};

const input = $input.first().json;

if (input.hasPhoto) {
  // Download and analyze the image
  return {
    action: 'analyze',
    photoId: input.photoId,
    content: input.content,
    systemPrompt: input.systemPrompt
  };
} else {
  // Generate image suggestions
  return {
    action: 'suggest',
    content: input.content,
    systemPrompt: input.systemPrompt
  };
}

