parameters.functionCode:
const input = $input.first().json;

if (input.action === 'analyze') {
  const analysis = input.choices[0].message.content;
  const includeInPost = analysis.toLowerCase().includes('yes') || analysis.toLowerCase().includes('include');
  const imageUrl = includeInPost ? `data:image/jpeg;base64,${input.body.toString('base64')}` : null;
  return {
    includeInPost: includeInPost,
    imageUrl: imageUrl,
    imageAnalysis: analysis,
    recommendations: ['Image analyzed', 'Decision made based on content fit'],
    generateNew: !includeInPost,
    imageDescription: includeInPost ? null : `Create an attention-grabbing LinkedIn visual based on: ${input.content}` ,
    chatId: input.chatId
  };
} else {
  const suggestions = input.choices[0].message.content;
  return {
    includeInPost: false,
    imageUrl: null,
    imageAnalysis: 'No image provided',
    recommendations: suggestions.split('
').filter(s => s.trim()),
    generateNew: true,
    imageDescription: suggestions || `Create professional LinkedIn visual for: ${input.content}` ,
    chatId: input.chatId
  };
}

const input = $input.first().json;
if (input.data && input.data[0] && input.data[0].b64_json) {
  return { includeInPost: true, imageUrl: `data:image/png;base64,${input.data[0].b64_json}`, imageAnalysis: 'Generated image', recommendations: [], generateNew: false, chatId: input.chatId };
}
return { includeInPost: false, imageUrl: null, imageAnalysis: 'Image generation failed', recommendations: [], generateNew: false, chatId: input.chatId };
